    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xB2AF7D82464434D5ULL + 0xEB457637FD4371F8ULL);
