            aOrbiterB = ((aWandererB + RotL64(aIngress, 43U)) + RotL64(aCarry, 23U)) + 0xEEC9CF44B997D236ULL;
            aOrbiterI = (((aWandererF + RotL64(aPrevious, 35U)) + RotL64(aCarry, 51U)) + 0x8136F202199F1D50ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterD = (aWandererD + RotL64(aCross, 29U)) + 0x6421681456FE5309ULL;
            aOrbiterG = (aWandererC + RotL64(aScatter, 39U)) + 0x566FA995625E5B8BULL;
            aOrbiterA = (aWandererJ + RotL64(aIngress, 19U)) + 0xB2B7B759EDAA065DULL;
            aOrbiterK = (aWandererH + RotL64(aCross, 56U)) + 0xC3847AD3B4CDA6ACULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xE985872CDF968FB6ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 17U)) & S_SALT1];
