            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xEA076B3B9FAF19C3ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x811374C059E4F107ULL), 35U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x4AA8BE3D83241AD9ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x7E228BF5B475D5E2ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x7EB65406220E3F13ULL), 3U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC834B3A307D1E53DULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0xECD0469564F50990ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF03375AA53E20E8BULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x2AD88E4587147B38ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x42BC294569635854ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x7D0B1615F250F385ULL), 13U);
            //
