            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xC851A3A1D622EED4ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterK) ^ 0xD7EBCC566A261327ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xEE258898E94FD333ULL), 11U);
            //
