            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x5AC4A2BF7E35369EULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0xFDB71FCEAA36CDB1ULL;
