            aScatter = (RotL64(aCarry, 53U) + RotL64(aIngress, 36U)) ^ (RotL64(aCross, 23U) + RotL64(aPrevious, 3U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterC = ((aWandererK + RotL64(aPrevious, 13U)) + RotL64(aCarry, 5U)) + 0xCE8A238F98B05319ULL;
            aOrbiterF = (aWandererH + RotL64(aCross, 47U)) + 0x97577C1A29998F6BULL;
            aOrbiterG = (((aWandererC + RotL64(aIngress, 29U)) + RotL64(aCarry, 53U)) + 0x3D1B58B29C3EEB8FULL) + aTwistOrbiterAssignSaltF[((aIndex + 8U)) & S_SALT1];
