            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x80F6F36B1237B551ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x1DB0BE7CC5ABB5E6ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x625475C3BC60AAF5ULL), 23U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0xD9237C3814D096E0ULL;
