    std::uint64_t *aKeyRotateAWandererUpdateSaltF = pWorkSpace->mDomainBundle.mKeyRotateASalts.mWandererUpdate.mSaltF;
    const std::uint64_t &aKeyRotateADomainWordIngress = pWorkSpace->mDomainBundle.mKeyRotateAConstants.mIngress;
