            aOrbiterJ = ((aWandererD + RotL64(aPrevious, 40U)) + RotL64(aCarry, 3U)) + 0x256184D716ED3662ULL;
            aOrbiterD = (((aWandererB + RotL64(aCross, 19U)) + RotL64(aCarry, 43U)) + 0x0CA483CCE13AC5B6ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 8U)) & S_SALT1];
            aOrbiterH = ((aWandererG + RotL64(aIngress, 29U)) + 0xE52A1DF5ADED2E8DULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterB = (aWandererC + RotL64(aPrevious, 47U)) + 0xACB8375E8702D7B0ULL;
            aOrbiterA = (aWandererJ + RotL64(aScatter, 13U)) + 0x4ADF040DB6559DC0ULL;
            aOrbiterC = (aWandererF + RotL64(aIngress, 58U)) + 0x3576612DAEFA0EC9ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x936C47BA95B79265ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x39CA096B1ABD6783ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x56298C16C18C1085ULL), 47U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xC943EC509B678C19ULL;
