            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0xEC30C75D989ACCD1ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xBA323E94A886C17DULL;
