            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0xE632AF3F2EA5FD7DULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x63938428826DDAE4ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x619868DB1AC7A919ULL), 29U);
