            aCarry = aCarry + (RotL64(aWandererE, 46U) ^ aWandererB);
            aCarry = aCarry + (RotL64(aWandererF, 23U) ^ aWandererJ);
            aCarry = aCarry + RotL64(aWandererI, 11U);
            aCarry = aCarry + RotL64(aIngress, 37U);
