            aWandererB = aWandererB ^ ((RotL64(aIngress, 39U) + aOrbiterK) + RotL64(aOrbiterD, 27U));
            aWandererG = aWandererG + ((((RotL64(aScatter, 5U) + RotL64(aOrbiterC, 60U)) + aOrbiterI) + RotL64(aCarry, 39U)) + aKeyRotateAWandererUpdateSaltA[((aIndex + 12U)) & S_SALT1]);
