            aOrbiterD = (((aWandererG + RotL64(aScatter, 5U)) + RotL64(aCarry, 41U)) + 0x80CDEE49C371B97AULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 29U)) & S_SALT1];
            aOrbiterJ = ((aWandererB + RotL64(aPrevious, 47U)) + 0x68DE7C4EE30A5AD4ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 11U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aIngress, 29U)) + RotL64(aCarry, 13U)) + 0xE55D1C5E0FC9CE7CULL;
            aOrbiterG = ((aWandererC + RotL64(aPrevious, 11U)) + RotL64(aCarry, 57U)) + 0x325737B5A3A752DBULL;
            aOrbiterA = (aWandererJ + RotL64(aCross, 21U)) + 0x57489D64C0A534C1ULL;
