            aOrbiterG = RotL64((aOrbiterG * 0xE97A6C8F1CE06F69ULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterF) + 0xFCB40EFB034E9F14ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterG) ^ 0xA4DBAF116DE841BFULL;
            aOrbiterE = RotL64((aOrbiterE * 0x87A84E79D041D101ULL), 13U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterB) + 0x88D334FA7592BD9CULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterA = ((aOrbiterA ^ aOrbiterF) ^ 0xDD258D26F5ADF87DULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xE45EECCC1491BB2FULL), 5U);
